(function(root,factory){const api=factory(root);if(typeof module==='object'&&module.exports)module.exports=api;if(typeof globalThis!=='undefined')globalThis.KeywordOSPurchaseOrderPlanningTest=api;if(root){root.KeywordOSPurchaseOrderPlanning=api;api.start?.();}})(typeof window!=='undefined'?window:null,function(root){
'use strict';
const STATUS='Planning only - not submitted';
function planner(){return root?.KeywordOSGrowth?.replenishmentPlan||globalThis.KeywordOSGrowthTest?.replenishmentPlan;}
function purchaseOrderPlanRow(row,{leadTimeDays,safetyDays=0}={},planFn=planner()){if(!row)return{available:false,reason:'Choose an inventory SKU.'};if(typeof planFn!=='function')return{available:false,reason:'Replenishment planner is unavailable.'};const plan=planFn({available:row.available,inbound:row.inbound,reserved:row.reserved,dailySales:row.velocity?.unitsPerDay,leadTimeDays,safetyDays});if(!plan.available)return plan;const snapshot=/^\d{4}-\d{2}-\d{2}$/.test(String(row.date||''))?new Date(`${row.date}T00:00:00Z`):null,dateAfter=days=>snapshot?new Date(snapshot.valueOf()+Math.max(0,days)*86400000).toISOString().slice(0,10):'';return{available:true,status:STATUS,sku:String(row.sku||''),product:String(row.product||''),snapshotDate:String(row.date||''),availableUnits:+row.available||0,inboundUnits:+row.inbound||0,reservedUnits:+row.reserved||0,observedUnitsPerDay:+row.velocity?.unitsPerDay||0,observedDays:+row.velocity?.observedDays||0,leadTimeDays:+leadTimeDays,safetyDays:+safetyDays||0,sellableUnits:plan.sellable,targetCoverageUnits:plan.target,coverageGapUnits:Math.ceil(plan.recommendedQuantity),daysUntilReview:plan.daysUntilReorder,daysToStockout:plan.daysToStockout,reviewDate:dateAfter(Math.floor(plan.daysUntilReorder)),forecastStockoutDate:dateAfter(plan.daysToStockout)};}
function csvCell(value){const text=String(value??'');return/[",\r\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text;}
function purchaseOrderPlanCsv(rows=[]){const valid=rows.filter(row=>row?.available);if(!valid.length)throw new Error('No purchase-order planning rows are available.');const headers=['Status','SKU','Product','Snapshot Date','Available Units','Inbound Units','Reserved Units','Observed Units/Day','Observed Days','Lead Time Days','Safety Days','Sellable Units','Target Coverage Units','Coverage Gap Units','Days Until Review','Review Date','Days To Stockout','Forecast Stockout Date'];return[headers.join(','),...valid.map(row=>[row.status,row.sku,row.product,row.snapshotDate,row.availableUnits,row.inboundUnits,row.reservedUnits,row.observedUnitsPerDay.toFixed(4),row.observedDays,row.leadTimeDays,row.safetyDays,row.sellableUnits.toFixed(4),row.targetCoverageUnits.toFixed(4),row.coverageGapUnits,row.daysUntilReview.toFixed(2),row.reviewDate,row.daysToStockout.toFixed(2),row.forecastStockoutDate].map(csvCell).join(','))].join('\n');}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function currentPlan(){const content=root?.document?.getElementById('content'),sku=content?.querySelector('[data-replenish-sku]')?.value,lead=content?.querySelector('[data-replenish-lead]')?.value,safety=content?.querySelector('[data-replenish-safety]')?.value,row=root?.KeywordOSGrowth?.replenishmentRows?.().find(item=>item.sku===sku);return purchaseOrderPlanRow(row,{leadTimeDays:lead,safetyDays:safety});}
function previewHtml(plan){if(!plan.available)return`<span class="muted">${escapeHtml(plan.reason)}</span>`;return`<div class="growth-kpis"><div class="growth-kpi"><span>Coverage gap</span><b>${plan.coverageGapUnits.toLocaleString('en-US')} units</b><small>Planning quantity only</small></div><div class="growth-kpi"><span>Review</span><b>${escapeHtml(plan.reviewDate||`${plan.daysUntilReview.toFixed(1)} days`)}</b><small>${plan.daysUntilReview.toFixed(1)} days from snapshot</small></div><div class="growth-kpi"><span>Forecast stockout</span><b>${escapeHtml(plan.forecastStockoutDate||`${plan.daysToStockout.toFixed(1)} days`)}</b><small>Observed Ads velocity</small></div></div><div class="top-gap muted">${STATUS}. Export contains the selected SKU, imported inventory snapshot and observed velocity inputs; it does not create or submit a purchase order.</div>`;}
function refresh(){const output=root?.document?.querySelector('[data-po-planning-preview]');if(output)output.innerHTML=previewHtml(currentPlan());}
function download(){const plan=currentPlan();if(!plan.available){root?.KeywordOSUIBridge?.toast?.(plan.reason||'PO planning unavailable','error');refresh();return;}const csv='\uFEFF'+purchaseOrderPlanCsv([plan]),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=root.document.createElement('a');a.href=url;a.download=`KeywordOS_PO_planning_${(plan.sku||'SKU').replace(/[^A-Za-z0-9._-]+/g,'_')}_${plan.snapshotDate||new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);root?.KeywordOSUIBridge?.toast?.('PO planning CSV downloaded; nothing was submitted','success');}
let scheduled=false;function inject(){scheduled=false;if(!root?.document||!String(root.location?.hash||'').startsWith('#page=inventory-risk'))return;const content=root.document.getElementById('content');if(!content||content.querySelector('#po-planning-panel'))return;const calculator=content.querySelector('[data-replenish-sku]'),html=calculator?`<div id="po-planning-panel" class="card top-gap"><div class="card-head"><div class="card-title"><h3>Purchase-order planning export</h3><small>Uses the selected SKU and the lead-time / safety-stock inputs above. Local planning only; no Amazon or supplier submission.</small></div></div><div class="card-body" data-po-planning-preview></div><div class="card-body"><button class="btn primary" data-po-export>Download planning CSV</button></div></div>`:`<div id="po-planning-panel" class="notice-banner top-gap">Purchase-order planning export unavailable until the replenishment calculator has a SKU with dated sales evidence.</div>`;content.insertAdjacentHTML('beforeend',html);content.querySelector('[data-po-export]')?.addEventListener('click',download);content.querySelectorAll('[data-replenish-sku],[data-replenish-lead],[data-replenish-safety]').forEach(element=>{element.addEventListener('input',refresh);element.addEventListener('change',refresh)});refresh();}
function schedule(){if(scheduled)return;scheduled=true;setTimeout(inject,0);}
function start(){if(!root?.document)return;const boot=()=>{const content=root.document.getElementById('content');if(!content)return;schedule();new MutationObserver(schedule).observe(content,{childList:true,subtree:false});root.addEventListener('hashchange',schedule);};root.document.readyState==='loading'?root.document.addEventListener('DOMContentLoaded',boot,{once:true}):boot();}
return{STATUS,purchaseOrderPlanRow,purchaseOrderPlanCsv,start};
});
